BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-036','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第2條、第13條、第20條、第22條（服務計畫不包括單純、偶發，基於家庭或友誼原因之服務；須具專門執業證照之工作應由具證照之志工為之；憑榮譽卡僅收費之公立風景區、未編定座次之康樂場所及文教設施免費；志工依指示服務侵害他人權利由運用單位負賠償責任），最後修正公布日：第2條 2001-01-20（制定公布）、第13條 2001-01-20（制定公布）、第20條 2013-06-11、第22條 2001-01-20（制定公布），本題考試日 2026-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP104-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第5條之1、第6條、第7條、第16條（中央主管機關每五年舉辦調查研究；集體從事志願服務之公、民營事業團體「應」與運用單位簽訂服務協議；志願服務計畫之內容；運用單位應辦理意外事故保險），最後修正公布日：第5條之1 2013-06-11、第6條 2001-01-20（制定公布）、第7條 2001-01-20（制定公布）、第16條 2001-01-20（制定公布），本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP105-2-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第5條、第5條之1、第15條、第20條（聯繫會報每年至少召開一次；中央主管機關每五年舉辦調查研究；志工應拒絕收取報酬；民防等編組成員準用榮譽卡予以半價優待），最後修正公布日：第5條 2013-06-11、第5條之1 2013-06-11、第15條 2014-06-18、第20條 2013-06-11，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP106-1-01','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第22條（志工依運用單位指示服務，因故意或過失不法侵害他人權利者，由志願服務運用單位負損害賠償責任），最後修正公布日：第22條 2001-01-20（制定公布），本題考試日 2017-02-18 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP107-2-29','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第20條（服務年資滿三年、服務時數達三百小時以上得申請志願服務榮譽卡），最後修正公布日：第20條 2013-06-11，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP108-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第20條（榮譽卡由地方主管機關核發，憑卡進入收費之公立風景區等免費，民防等編組成員準用予以半價優待），最後修正公布日：第20條 2013-06-11，本題考試日 2019-01-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP108-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第5條之1（中央主管機關應至少每五年舉辦志願服務調查研究並出版統計報告），最後修正公布日：第5條之1 2013-06-11，本題考試日 2019-07-27 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP109-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第16條、第17條、第19條、第20條（意外事故保險、服務績效證明書、定期考核服務績效；榮譽卡須年資滿三年、時數達三百小時），最後修正公布日：第16條 2001-01-20（制定公布）、第17條 2001-01-20（制定公布）、第19條 2001-01-20（制定公布）、第20條 2013-06-11，本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP110-1-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第14條、第15條（獲得從事服務之完整資訊為志工之權利，非義務），最後修正公布日：第14條 2001-01-20（制定公布）、第15條 2014-06-18，本題考試日 2021-02-06 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP110-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第5條、第11條、第12條、第16條（志願服務聯繫會報由主管機關及各目的事業主管機關召開，非運用單位職責），最後修正公布日：第5條 2013-06-11、第11條 2001-01-20（制定公布）、第12條 2001-01-20（制定公布）、第16條 2001-01-20（制定公布），本題考試日 2021-08-21 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP114-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第18條（各目的事業主管機關得將汰舊之器材及設備無償撥交志願服務運用單位使用），最後修正公布日：第18條 2013-06-11，本題考試日 2025-02-08 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131'),('SP114-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考志願服務法第6條、第9條、第11條、第12條（志願服務證及服務紀錄冊之管理辦法由中央主管機關定之），最後修正公布日：第6條 2001-01-20（制定公布）、第9條 2001-01-20（制定公布）、第11條 2001-01-20（制定公布）、第12條 2001-01-20（制定公布），本題考試日 2025-07-26 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050131');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>12 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>12 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'a90e72c1e7986cfdcf74fc23e541ef04' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_12, count(*) FILTER (WHERE q.legal_status='changed') changed_0, count(*) total_12 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
